const CALLBACK_MAX_BYTES = 64;
const MESSAGE_MAX_CHARS = 4096;

const ACTIONS = {
  APPROVE_SEND: "apv",
  SKIP_DRAFT: "skp",
  NEXT_DRAFT: "nxt",
  DRAFT_ASSIST: "ast",
  SEND_ASSIST: "snd",
  DISCARD_ASSIST: "dis",
  MARK_RESOLVED: "res",
  SEND_CONFIRMATION: "cnf",
