    "",
  ];

  leases.slice(0, 15).forEach((lease) => {
    lines.push(`• ${escapeHtml(lease.tenant_name)}, ${escapeHtml(lease.unit)} — ends ${formatDate(lease.lease_end_date)}`);
  });

  return { text: truncate(lines.join("\n"), MESSAGE_MAX_CHARS) };
