function buildRetryPrompt(failures, config) {
  const rows = failures.map((failure) => ({
    lease_id: failure.lease.lease_id,
    tenant_first_name: failure.lease.tenant_first_name,
    unit: failure.lease.unit,
    tenure_months: failure.lease.tenure_months,
    manager_name: config.manager_name || "Maya Chen",
    company_name: config.company_name || "Harborview Property Management",
    previous_violations: failure.violations,
  }));

  if (!rows.length) {
    return "No drafts failed deterministic guardrails. Return {\"drafts\":[]}.";
  }

  return [
    "Rewrite only the rows below. The previous drafts failed deterministic guardrails.",
    "Avoid every named violation. Return a JSON object with a drafts array using the exact lease_id values.",
    "",
    JSON.stringify({ failed_rows: rows }, null, 2),
  ].join("\n");
}

function eligibleDraftRows(leases, cohort) {
  const seen = new Set();
  return toArray(leases)
    .filter((lease) => normalizeText(lease.lease_id))
    .filter((lease) => normalizeText(lease.cohort) === normalizeText(cohort || "90"))
    .filter((lease) => normalizeText(lease.status).toUpperCase() === "PENDING")
    .filter((lease) => normalizeBool(lease.email_valid))
    .filter((lease) => !normalizeBool(lease.opted_out))
    .sort((a, b) => Number(a.days_to_expiry || 9999) - Number(b.days_to_expiry || 9999))
    .filter((lease) => {
      const leaseId = normalizeText(lease.lease_id);
      if (seen.has(leaseId)) return false;
      seen.add(leaseId);
      return true;
    });
}

function makeDraftRow(lease, draft, refToken, status, guard) {
  const subject = status === "DRAFT"
    ? appendRefToken(draft.subject, refToken)
    : appendRefToken("Needs manager wording", refToken);
  const body = status === "DRAFT"
    ? normalizeText(draft.body)
    : `Guardrail failed: ${guard.violations.join("; ")}`;

  return {
    ...lease,
    status,
    draft_subject: subject,
    draft_body: body,
    ref_token: refToken,
    _guardrail: guard,
  };
}

function finalizeDraftsFromBatch(candidates, firstDrafts, retryDrafts, config) {
  const firstByLease = new Map(firstDrafts.map((draft) => [draft.lease_id, draft]));
  const retryByLease = new Map(retryDrafts.map((draft) => [draft.lease_id, draft]));
  const usedTokens = new Set();
  const finalRows = [];
  const failures = [];

  for (const lease of candidates) {
    const first = firstByLease.get(lease.lease_id);
    let draft = first ? repairDraftForLease(lease, first) : null;
    let guard = draft ? guardDraft(lease, draft.subject, draft.body) : {
      ok: false,
      violations: ["missing draft from model output"],
      word_count: 0,
      question_count: 0,
    };

    if (!guard.ok) {
      failures.push({ lease, violations: guard.violations });
      const retry = retryByLease.get(lease.lease_id);
      if (retry) {
        const repairedRetry = repairDraftForLease(lease, retry);
        const retryGuard = guardDraft(lease, repairedRetry.subject, repairedRetry.body);
        if (retryGuard.ok) {
          draft = repairedRetry;
          guard = retryGuard;
        } else {
          guard = retryGuard;
          draft = repairedRetry;
        }
      }
    }

    const token = refTokenForLease(lease, usedTokens);
    finalRows.push(makeDraftRow(
      lease,
      draft || { subject: "", body: "" },
      token,
      guard.ok ? "DRAFT" : "REVIEW_FAILED",
      guard,
    ));
  }

  return {
    rows: finalRows,
    failures,
    generated_count: finalRows.filter((row) => row.status === "DRAFT").length,
    review_failed_count: finalRows.filter((row) => row.status === "REVIEW_FAILED").length,
    model: config.model_draft || "gpt-5.6-luna",
  };
}

function prepareApprovalChanges(action, body, leases) {
  const normalizedAction = normalizeText(action).toLowerCase();
  const leaseId = normalizeText(body.lease_id);
  const changes = [];

  function rowById(id) {
    return toArray(leases).find((lease) => normalizeText(lease.lease_id) === id);
  }

  function applyEditedFields(lease) {
    const updated = { ...lease };
    if (Object.prototype.hasOwnProperty.call(body, "edited_subject")) {
      updated.draft_subject = appendRefToken(body.edited_subject, normalizeText(lease.ref_token));
    }
    if (Object.prototype.hasOwnProperty.call(body, "edited_body")) {
      updated.draft_body = normalizeText(body.edited_body);
    }
    return updated;
  }

  if (normalizedAction === "approve_all") {
    for (const lease of toArray(leases)) {
      if (normalizeText(lease.status).toUpperCase() !== "DRAFT") continue;
      const guard = guardDraft(lease, lease.draft_subject, lease.draft_body);
      if (guard.ok) changes.push({ ...lease, status: "APPROVED", _approval_action: "approve_all" });
    }
    return changes;
  }

  if (!leaseId) throw new Error("lease_id is required for approve, edit, and skip actions.");
  const lease = rowById(leaseId);
  if (!lease) throw new Error(`No lease row found for lease_id ${leaseId}.`);

  if (normalizedAction === "skip") {
    changes.push({ ...lease, status: "SKIPPED", _approval_action: "skip" });
    return changes;
  }

  if (!["edit", "approve"].includes(normalizedAction)) {
    throw new Error(`Unsupported approval action: ${normalizedAction}`);
  }

  const updated = applyEditedFields(lease);
  const guard = guardDraft(updated, updated.draft_subject, updated.draft_body);
  if (!guard.ok) {
    throw new Error(`Edited draft failed guardrail: ${guard.violations.join("; ")}`);
  }

  updated.status = normalizedAction === "approve" ? "APPROVED" : normalizeText(lease.status).toUpperCase() || "DRAFT";
  updated._approval_action = normalizedAction;
  changes.push(updated);
  return changes;
}

function buildFooter(config) {
  const company = config.company_name || "Harborview Property Management";
  const manager = config.manager_name || "Maya Chen";
  return [
    "",
    "--",
    manager,
    company,
    "Demo check-in only. This is not a renewal offer, notice, or lease document.",
  ].join("\n");
}

function prepareSendCandidates(body, leases, config) {
  const requested = Array.isArray(body.lease_ids)
    ? new Set(body.lease_ids.map((id) => normalizeText(id)).filter(Boolean))
    : null;
  const demoEmail = normalizeText(config.demo_recipient_email).toLowerCase();
  const footer = buildFooter(config);
  const delay = Math.max(0, Number(config.send_delay_seconds || 0) || 0);

  return toArray(leases)
    .filter((lease) => normalizeText(lease.lease_id))
    .filter((lease) => !requested || requested.has(normalizeText(lease.lease_id)))
    .filter((lease) => normalizeText(lease.status).toUpperCase() === "APPROVED")
    .filter((lease) => normalizeBool(lease.email_valid))
    .filter((lease) => !normalizeBool(lease.opted_out))
    .filter((lease) => guardDraft(lease, lease.draft_subject, lease.draft_body).ok)
    .sort((a, b) => {
      const aPriority = demoEmail && normalizeText(a.email).toLowerCase() === demoEmail ? 0 : 1;
      const bPriority = demoEmail && normalizeText(b.email).toLowerCase() === demoEmail ? 0 : 1;
      if (aPriority !== bPriority) return aPriority - bPriority;
      return normalizeText(a.tenant_name).localeCompare(normalizeText(b.tenant_name));
    })
    .map((lease, index) => ({
      ...lease,
      status: "SENDING",
      _send_body: `${normalizeText(lease.draft_body)}${footer}`,
      _sender_name: config.manager_name || "Maya Chen",
      _send_delay_seconds: index === 0 ? 0 : delay,
      _is_demo_priority: demoEmail && normalizeText(lease.email).toLowerCase() === demoEmail,
    }));
}

function sentEventForLease(lease, sentAt) {
  return {
    event_id: `sent-${sentAt.replace(/[^0-9A-Za-z]/g, "")}-${normalizeText(lease.lease_id)}`,
    lease_id: lease.lease_id,
    event_type: "SENT",
    reply_text: "",
    intent: "",
    grievance_category: "",
    grievance_summary: "",
    urgency: "",
    compliance_flag: "",
    confidence: "",
    requires_human: false,
    created_at: sentAt,
  };
}

const routed = $('Route Telegram Update').first().json;
const leases = flattenAirtable($('Airtable Read Leases For Action').all());
const configRows = flattenAirtable($('Airtable Read Config For Action').all());
const config = configMap(configRows);

// A pending edit remembers which draft the manager tapped Edit on, so the next
// plain message they send can be applied to the right resident and field.
const pendingRow = configRows.find((row) => row.key === 'pending_edit') || null;
const pendingParts = String((pendingRow && pendingRow.value) || '').split('|');
const pendingRecordId = pendingParts[0] || '';
const pendingField = pendingParts[1] || 'draft_body';

const action = routed.action;
const targetRecordId = action === 'edt_apply' ? pendingRecordId : routed.record_id;
const lease = leases.find((row) => row.record_id === targetRecordId) || null;
const status = lease ? String(lease.status || '').toUpperCase() : '';

// The approval queue, ordered the same way WF7 orders it, so Next walks the
// remaining drafts in a predictable sequence.
const queue = leases
  .filter((row) => String(row.status || '').toUpperCase() === 'AWAITING_APPROVAL')
  .sort((a, b) => {
    const priority = (b.is_demo_priority ? 1 : 0) - (a.is_demo_priority ? 1 : 0);
    if (priority !== 0) return priority;
    return Number(a.days_to_expiry || 9999) - Number(b.days_to_expiry || 9999);
  });
const queueIndex = queue.findIndex((row) => row.record_id === targetRecordId);
const nextRecordId = queueIndex >= 0 && queue[queueIndex + 1]
  ? queue[queueIndex + 1].record_id
  : (queue[0] && queue[0].record_id !== targetRecordId ? queue[0].record_id : '');

const result = {
  action,
  record_id: targetRecordId,
  edit_text: routed.edit_text || '',
  queue_total: queue.length,
  queue_position: queueIndex >= 0 ? queueIndex + 1 : 0,
  next_record_id: nextRecordId,
  edit_field: pendingField,
  pending_config_record_id: pendingRow ? pendingRow.record_id : '',
  chat_id: routed.chat_id,
  callback_query_id: routed.callback_query_id,
  config,
  lease,
  needs_openai: false,
  needs_gmail: false,
  outcome: 'ok',
  prompt: '',
  instructions: '',
  model: config.model_draft || 'gpt-5.6-luna',
};

if (action === 'edt_apply' && !pendingRecordId) {
  result.outcome = 'no_pending_edit';
  result.text = 'Nothing is waiting to be edited. Tap "Edit wording" on a draft first, then send the new text.';
  return [{ json: result }];
}

if (!lease) {
  result.outcome = 'missing_record';
  result.text = 'That resident record could not be found.';
  return [{ json: result }];
}

// Idempotency guards. A second tap must never produce a second email.
if (action === ACTIONS.APPROVE_SEND && status === 'SENT') {
  result.outcome = 'already_sent';
  result.text = 'Already sent to ' + lease.tenant_name + '. No second email was sent.';
  return [{ json: result }];
}

if (action === ACTIONS.APPROVE_SEND && status !== 'AWAITING_APPROVAL') {
  result.outcome = 'not_approvable';
  result.text = 'That draft is no longer awaiting approval (status ' + status + ').';
  return [{ json: result }];
}

if (action === ACTIONS.SEND_CONFIRMATION && lease.confirmation_sent_at) {
  result.outcome = 'already_sent';
  result.text = 'The confirmation was already sent.';
  return [{ json: result }];
}

// Skip may only retire a draft that is still awaiting a decision. Skipping an
// already-sent resident would clear the sent record and make them eligible for
// a second check-in, so it is refused outright.
if (action === ACTIONS.SKIP_DRAFT && status !== 'AWAITING_APPROVAL' && status !== 'REVIEW_FAILED') {
  result.outcome = 'not_skippable';
  result.text = status === 'SENT'
    ? 'Already sent to ' + lease.tenant_name + '. Skip does nothing once a message has gone out.'
    : 'There is no pending draft to skip (status ' + status + ').';
  return [{ json: result }];
}

if (action === ACTIONS.APPROVE_SEND) {
  result.needs_gmail = true;
} else if (action === ACTIONS.SEND_ASSIST) {
  if (!String(lease.assist_draft || '').trim()) {
    result.outcome = 'no_draft';
    result.text = 'There is no drafted reply to send.';
  } else {
    result.needs_gmail = true;
  }
} else if (action === ACTIONS.DRAFT_ASSIST) {
  result.needs_openai = true;
  result.instructions = 'Return only JSON with keys subject and body.';
  result.prompt = buildAssistPrompt(lease, config);
} else if (action === ACTIONS.MARK_RESOLVED) {
  result.needs_openai = true;
  result.instructions = 'Return only JSON with keys subject and body.';
  result.prompt = buildConfirmationPrompt(lease, config);
} else if (action === ACTIONS.SEND_CONFIRMATION) {
  result.needs_gmail = Boolean(String(lease.assist_draft || '').trim());
  if (!result.needs_gmail) {
    result.outcome = 'no_draft';
    result.text = 'There is no confirmation message to send.';
  }
}

return [{ json: result }];

function flattenAirtable(items) {
  const out = [];
  for (const item of items || []) {
    const records = item && item.json && Array.isArray(item.json.records) ? item.json.records : [];
    for (const record of records) {
      out.push(Object.assign({ record_id: record.id }, record.fields || {}));
    }
  }
  return out;
}

function configMap(rows) {
  const map = {};
  for (const row of rows || []) {
    if (row.key) map[row.key] = row.value;
  }
  return map;
}

/**
 * Telegram card and inline-keyboard builders for the v2 demo.
 *
 * This file is inlined into n8n Code nodes at import time, the same way the v1
 * stage libraries are, so it must stay dependency-free and browser-safe.
 *
 * Telegram constraints enforced here:
 *  - callback_data must be 64 bytes or fewer. Actions use 3-character prefixes
 *    plus an Airtable record id (17 chars), so the longest payload is ~21 bytes.
 *  - message text must be 4096 characters or fewer. Long drafts are truncated
 *    for display only; the stored draft is never shortened.
 *  - only one Telegram Trigger may be active per bot, so every button in this
 *    file is routed through WF6.
 */

const CALLBACK_MAX_BYTES = 64;
const MESSAGE_MAX_CHARS = 4096;

const ACTIONS = {
  APPROVE_SEND: "apv",
  SKIP_DRAFT: "skp",
  NEXT_DRAFT: "nxt",
  DRAFT_ASSIST: "ast",
  SEND_ASSIST: "snd",
  DISCARD_ASSIST: "dis",
  MARK_RESOLVED: "res",
  SEND_CONFIRMATION: "cnf",
  ACK_HANDOFF: "hnd",
  EDIT_DRAFT: "edt",
};

function textOf(value) {
  return value == null ? "" : String(value).trim();
}

function escapeHtml(value) {
  return textOf(value)
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;");
}

function truncate(value, limit) {
  const text = textOf(value);
  if (text.length <= limit) return text;
  return `${text.slice(0, Math.max(0, limit - 1))}…`;
}

/** Encodes a button payload and fails loudly rather than letting Telegram reject it. */
function encodeCallback(action, recordId) {
  const payload = `${action}:${textOf(recordId)}`;
  const size = Buffer.byteLength(payload, "utf8");
  if (size > CALLBACK_MAX_BYTES) {
    throw new Error(`callback_data is ${size} bytes, over Telegram's ${CALLBACK_MAX_BYTES}-byte cap: ${payload}`);
  }
  return payload;
}

function decodeCallback(callbackData) {
  const raw = textOf(callbackData);
  const separator = raw.indexOf(":");
  if (separator === -1) return { action: raw, record_id: "" };
  return {
    action: raw.slice(0, separator),
    record_id: raw.slice(separator + 1),
  };
}

function keyboard(rows) {
  return { inline_keyboard: rows.filter((row) => row && row.length) };
}

function button(label, action, recordId) {
  return { text: label, callback_data: encodeCallback(action, recordId) };
}

function formatDate(value) {
  const text = textOf(value);
  if (!text) return "unknown";
  const parsed = new Date(text);
  if (Number.isNaN(parsed.getTime())) return text;
  return parsed.toISOString().slice(0, 10);
}

function formatMoney(value) {
  const amount = Number(value || 0);
  if (!Number.isFinite(amount)) return "$0";
  return `$${Math.round(amount).toLocaleString("en-US")}`;
}

function badgeLine(lease) {
  return [
    textOf(lease.intent),
    textOf(lease.grievance_category) && textOf(lease.grievance_category) !== "NONE"
      ? textOf(lease.grievance_category)
      : "",
    textOf(lease.compliance_flag) && textOf(lease.compliance_flag) !== "NONE"
      ? textOf(lease.compliance_flag)
      : "",
    textOf(lease.urgency),
  ]
    .filter(Boolean)
    .join(" / ");
}

function residentHeader(lease) {
  const days = textOf(lease.days_to_expiry);
  const leaseEnd = formatDate(lease.lease_end_date);
  const tenure = textOf(lease.tenure_months);
  const parts = [`Lease ends ${leaseEnd}`];
  if (days) parts.push(`${days} days out`);
  if (tenure) parts.push(`${tenure} months resident`);
  return parts.join(" · ");
}

/* ------------------------------------------------------------------ cards */

/**
 * Summary posted once per generation run, before the individual draft cards.
 */
function generationSummaryCard(summary) {
  const lines = [
    `<b>${escapeHtml(summary.touch_label || "Check-ins")} drafted</b>`,
    "",
    `${summary.drafted_count} ready for review`,
  ];

  if (summary.review_failed_count) {
    lines.push(`${summary.review_failed_count} need wording (checks failed twice)`);
  }
  if (summary.handoff_count) {
    lines.push(`${summary.handoff_count} flagged for leasing handoff (no resident email)`);
  }
  if (summary.exposure != null) {
    lines.push("", `Turnover exposure in this window: <b>${formatMoney(summary.exposure)}</b>`);
  }

  lines.push("", "Nothing sends until you approve it.");

  return {
    text: lines.join("\n"),
    reply_markup: summary.first_record_id
      ? keyboard([[button("▶️ Review first draft", ACTIONS.NEXT_DRAFT, summary.first_record_id)]])
      : undefined,
  };
}

/**
 * A single draft awaiting approval. This is the core approval moment.
 */
function draftApprovalCard(lease, options = {}) {
  const lines = [
    `<b>${escapeHtml(lease.tenant_name)} · ${escapeHtml(lease.unit)}</b>`,
    residentHeader(lease),
    "",
    `<b>Subject:</b> ${escapeHtml(lease.draft_subject)}`,
    "",
    escapeHtml(truncate(lease.draft_body, 2400)),
  ];

  if (options.position && options.total) {
    lines.push("", `Draft ${options.position} of ${options.total}`);
  }

  const rows = [
    [
      button("✅ Approve & Send", ACTIONS.APPROVE_SEND, lease.record_id),
      button("⏭ Skip", ACTIONS.SKIP_DRAFT, lease.record_id),
    ],
  ];

  if (options.next_record_id) {
    rows.push([button("➡️ Next draft", ACTIONS.NEXT_DRAFT, options.next_record_id)]);
  }

  return { text: truncate(lines.join("\n"), MESSAGE_MAX_CHARS), reply_markup: keyboard(rows) };
}

/**
 * A draft that failed guardrails twice. Deliberately has no approve button.
 */
function reviewFailedCard(lease) {
  return {
    text: [
      `<b>Needs wording · ${escapeHtml(lease.tenant_name)}, ${escapeHtml(lease.unit)}</b>`,
      "",
      `The draft failed the safety checks twice: ${escapeHtml(lease.data_quality || "see workflow log")}`,
      "",
      "No approve button is offered. Write this one yourself.",
    ].join("\n"),
  };
}

/**
 * 30-day cohort handoff. Internal only - never emails the resident.
 */
function leasingHandoffCard(leases) {
  const lines = [
    `<b>Leasing handoff · ${leases.length} residents at 30 days</b>`,
    "",
    "These are inside the renewal-offer window. No resident email is sent from here — this is a handoff to your leasing team.",
    "",
  ];

  leases.slice(0, 15).forEach((lease) => {
    lines.push(`• ${escapeHtml(lease.tenant_name)}, ${escapeHtml(lease.unit)} — ends ${formatDate(lease.lease_end_date)}`);
  });

  return { text: truncate(lines.join("\n"), MESSAGE_MAX_CHARS) };
}

/**
 * A reply that needs a person. Mirrors the v1 alert content and adds actions.
 */
function atRiskAlertCard(lease, options = {}) {
  const complianceFlag = textOf(lease.compliance_flag);
  const isCompliance = complianceFlag && complianceFlag !== "NONE";

  const lines = [
    `<b>AT RISK · ${escapeHtml(lease.tenant_name)}, ${escapeHtml(lease.unit)}</b>`,
    residentHeader(lease),
    "",
    badgeLine(lease),
    "",
    `<i>"${escapeHtml(truncate(lease.reply_text, 1200))}"</i>`,
    "",
    `<b>Action:</b> ${escapeHtml(lease.suggested_action)}`,
    `Confidence: ${escapeHtml(lease.confidence)}`,
  ];

  if (isCompliance) {
    lines.push("", "<b>Nothing has been sent to the resident.</b> Compliance-sensitive: read it yourself before replying.");
  }

  const rows = [];

  // Compliance-sensitive replies get no one-tap assist. A person decides first.
  if (!isCompliance) {
    rows.push([button("✍️ Draft my reply", ACTIONS.DRAFT_ASSIST, lease.record_id)]);
  }
  if (options.allow_resolve !== false) {
    rows.push([button("✅ Mark resolved", ACTIONS.MARK_RESOLVED, lease.record_id)]);
  }

  return {
    text: truncate(lines.join("\n"), MESSAGE_MAX_CHARS),
    reply_markup: rows.length ? keyboard(rows) : undefined,
  };
}

/**
 * A drafted reply to the resident, awaiting explicit approval before it sends.
 */
function assistApprovalCard(lease) {
  return {
    text: truncate(
      [
        `<b>Suggested reply · ${escapeHtml(lease.tenant_name)}, ${escapeHtml(lease.unit)}</b>`,
        "",
        escapeHtml(truncate(lease.assist_draft, 2800)),
        "",
        "This has not been sent. Approve it and it goes to the resident as written.",
      ].join("\n"),
      MESSAGE_MAX_CHARS
    ),
    reply_markup: keyboard([
      [
        button("✅ Send reply", ACTIONS.SEND_ASSIST, lease.record_id),
        button("⏭ Discard", ACTIONS.DISCARD_ASSIST, lease.record_id),
      ],
    ]),
  };
}

/**
 * Confirmation that the issue is closed, plus the optional resident follow-up.
 */
function resolutionCard(lease, options = {}) {
  const lines = [
    `<b>Issue resolved · ${escapeHtml(lease.tenant_name)}, ${escapeHtml(lease.unit)}</b>`,
    "",
  ];

  if (lease.days_to_resolve != null && lease.days_to_resolve !== "") {
    lines.push(`Closed in ${lease.days_to_resolve} days.`);
  }
  if (options.exposure_recovered != null) {
    lines.push(`Turnover exposure recovered: <b>${formatMoney(options.exposure_recovered)}</b>`);
  }

  if (textOf(lease.assist_draft)) {
    lines.push("", "<b>Follow-up ready for the resident:</b>", "", escapeHtml(truncate(lease.assist_draft, 2000)));
    return {
      text: truncate(lines.join("\n"), MESSAGE_MAX_CHARS),
      reply_markup: keyboard([
        [
          button("✅ Send confirmation", ACTIONS.SEND_CONFIRMATION, lease.record_id),
          button("⏭ Skip", ACTIONS.DISCARD_ASSIST, lease.record_id),
        ],
      ]),
    };
  }

  return { text: truncate(lines.join("\n"), MESSAGE_MAX_CHARS) };
}

/**
 * A reply that could not be matched to a resident. Never guesses an owner.
 */
function unmatchedReplyCard(reply) {
  return {
    text: truncate(
      [
        "<b>Unmatched reply</b>",
        "",
        `From: ${escapeHtml(reply.from_email || "unknown sender")}`,
        `Subject: ${escapeHtml(reply.subject || "(none)")}`,
        "",
        `<i>"${escapeHtml(truncate(reply.reply_text, 1000))}"</i>`,
        "",
        "No reference code matched and the sender is not in the roster. No resident was assigned. Find the resident manually before replying.",
      ].join("\n"),
      MESSAGE_MAX_CHARS
    ),
  };
}

/** Daily sweep digest. */
function sweepDigestCard(summary) {
  return {
    text: [
      `<b>${escapeHtml(summary.company_name || "Portfolio")} daily sweep</b>`,
      "",
      `${summary.recomputed_count} residents checked`,
      `${summary.at_risk_count} at risk · ${summary.staying_count} staying · ${summary.escalated_count} newly escalated`,
      `${summary.issues_resolved || 0} issues resolved`,
      "",
      `Exposure open: <b>${formatMoney(summary.turnover_exposure)}</b>`,
      `Exposure recovered: <b>${formatMoney(summary.exposure_recovered)}</b>`,
    ].join("\n"),
  };
}

/** Short acknowledgement text shown in Telegram's toast after a button press. */
function acknowledgement(action, outcome) {
  const map = {
    [ACTIONS.APPROVE_SEND]: outcome === "already_sent" ? "Already sent" : "Approved and sent",
    [ACTIONS.SKIP_DRAFT]: "Skipped",
    [ACTIONS.NEXT_DRAFT]: "Loading next draft",
    [ACTIONS.DRAFT_ASSIST]: "Drafting a reply",
    [ACTIONS.SEND_ASSIST]: outcome === "already_sent" ? "Already sent" : "Reply sent",
    [ACTIONS.DISCARD_ASSIST]: "Discarded",
    [ACTIONS.MARK_RESOLVED]: "Marked resolved",
    [ACTIONS.SEND_CONFIRMATION]: outcome === "already_sent" ? "Already sent" : "Confirmation sent",
    [ACTIONS.ACK_HANDOFF]: "Acknowledged",
    [ACTIONS.EDIT_DRAFT]: "Waiting for your wording",
  };
  return map[action] || "Done";
}
/**
 * Cadence selection, prompts, and reply guardrails for the v2 demo.
 *
 * The v1 build had a single 90-day touch. v2 runs a four-stage program driven
 * entirely by cohort, which is derived from lease_end_date alone:
 *
 *   120 -> WATCH_120    watchlist only, no resident contact
 *    90 -> CHECK_IN_90  soft check-in, emailed on approval
 *    60 -> NUDGE_60     only for residents who never replied to the 90-day touch
 *    30 -> HANDOFF_30   internal leasing handoff, never emails the resident
 *
 * Draft guardrails for outbound check-ins are reused from
 * scripts/stage-5-outbound-lib.js. Replies and fix-confirmations need different
 * rules (they may reference the resident's issue and are not limited to one
 * question), so guardReply() is defined here.
 *
 * This file is inlined into n8n Code nodes at import time, so it stays
 * dependency-free.
 */

const TOUCH = {
  WATCH_120: "WATCH_120",
  CHECK_IN_90: "CHECK_IN_90",
  NUDGE_60: "NUDGE_60",
  HANDOFF_30: "HANDOFF_30",
};

const TOUCH_BY_COHORT = {
  120: TOUCH.WATCH_120,
  90: TOUCH.CHECK_IN_90,
  60: TOUCH.NUDGE_60,
  30: TOUCH.HANDOFF_30,
};

const TOUCH_LABEL = {
  [TOUCH.WATCH_120]: "120-day watchlist",
  [TOUCH.CHECK_IN_90]: "90-day check-ins",
  [TOUCH.NUDGE_60]: "60-day nudges",
  [TOUCH.HANDOFF_30]: "30-day leasing handoff",
};

/** Touches that may result in an email to a resident. */
const EMAILING_TOUCHES = new Set([TOUCH.CHECK_IN_90, TOUCH.NUDGE_60]);

function txt(value) {
  return value == null ? "" : String(value).trim();
}

function bool(value) {
  if (typeof value === "boolean") return value;
  const text = txt(value).toLowerCase();
  return text === "true" || text === "1" || text === "yes";
}

function daysBetween(fromIso, toIso) {
  const from = new Date(fromIso);
  const to = new Date(toIso);
  if (Number.isNaN(from.getTime()) || Number.isNaN(to.getTime())) return null;
  return Math.floor((to.getTime() - from.getTime()) / 86400000);
}

/**
 * Airtable stores no email_valid flag. Validity is derived from the address and
 * the data-quality notes written at seed time, mirroring v1's isValidEmail().
 */
function emailValidFor(lease) {
  const email = txt(lease.email);
  if (!email) return false;
  const notes = txt(lease.data_quality).toUpperCase();
  if (notes.includes("MISSING_EMAIL") || notes.includes("INVALID_EMAIL")) return false;
  return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);
}

function touchForCohort(cohort) {
  return TOUCH_BY_COHORT[txt(cohort)] || null;
}

/**
 * True when a resident received the 90-day check-in, enough time has passed, and
 * no meaningful reply ever came back. NO_SIGNAL auto-replies do not count as a reply.
 */
function isSilentAfterCheckIn(lease, logRows, config, nowIso) {
  if (txt(lease.status).toUpperCase() !== "SENT") return false;
  const sentAt = txt(lease.sent_at);
  if (!sentAt) return false;

  const elapsed = daysBetween(sentAt, nowIso);
  const threshold = Number(config.nudge_after_days || 14);
  if (elapsed == null || elapsed < threshold) return false;

  const meaningful = (logRows || []).some((row) => {
    if (txt(row.lease_id) !== txt(lease.lease_id)) return false;
    if (txt(row.event_type) !== "REPLY_RECEIVED") return false;
    return txt(row.intent).toUpperCase() !== "NO_SIGNAL";
  });

  return !meaningful;
}

/**
 * Splits the roster into the four cadence stages.
 * Nothing here consults anything except cohort, status, opt-out, and reply history.
 */
function selectTouchCandidates(leases, logRows, config, nowIso) {
  const result = {
    [TOUCH.WATCH_120]: [],
    [TOUCH.CHECK_IN_90]: [],
    [TOUCH.NUDGE_60]: [],
    [TOUCH.HANDOFF_30]: [],
    skipped: [],
  };

  const seen = new Set();

  for (const lease of leases || []) {
    const leaseId = txt(lease.lease_id);
    if (!leaseId || seen.has(leaseId)) continue;
    seen.add(leaseId);

    const touch = touchForCohort(lease.cohort);
    if (!touch) continue;

    if (bool(lease.opted_out)) {
      result.skipped.push({ lease, reason: "opted_out" });
      continue;
    }

    if (touch === TOUCH.WATCH_120 || touch === TOUCH.HANDOFF_30) {
      result[touch].push(lease);
      continue;
    }

    if (!emailValidFor(lease)) {
      result.skipped.push({ lease, reason: "no_usable_email" });
      continue;
    }

    if (touch === TOUCH.CHECK_IN_90) {
      if (txt(lease.status).toUpperCase() !== "PENDING") {
        result.skipped.push({ lease, reason: `status_${txt(lease.status).toLowerCase()}` });
        continue;
      }
      result[touch].push(lease);
      continue;
    }

    if (touch === TOUCH.NUDGE_60) {
      if (!isSilentAfterCheckIn(lease, logRows, config, nowIso)) {
        result.skipped.push({ lease, reason: "not_silent" });
        continue;
      }
      result[touch].push(lease);
    }
  }

  for (const touch of Object.keys(TOUCH_BY_COHORT).map((cohort) => TOUCH_BY_COHORT[cohort])) {
    result[touch].sort((a, b) => Number(a.days_to_expiry || 9999) - Number(b.days_to_expiry || 9999));
  }

  return result;
}

/* ---------------------------------------------------------------- prompts */

function touchPromptInstructions(touch) {
  const shared = [
    "You write short, plain, human property-management emails.",
    "Never mention rent, price, renewal, lease terms, deadlines, legal matters, or eviction.",
    "Never state or imply a date.",
    "Never mention software, automation, or AI.",
    "No exclamation marks, bullets, or emoji.",
    "Address the resident by first name.",
  ];

  if (touch === TOUCH.NUDGE_60) {
    return [
      ...shared,
      "This is a second, lighter message to a resident who did not reply to an earlier check-in.",
      "Acknowledge briefly that you reached out before, without any hint of pressure or complaint.",
      "Body must be 30 to 70 words and contain exactly one question.",
    ].join(" ");
  }

  return [
    ...shared,
    "This is a soft check-in months before any renewal conversation.",
    "Include one natural reference to how long they have lived there.",
    "Body must be 35 to 95 words and contain exactly one question about anything that is not sorted out.",
  ].join(" ");
}

function buildTouchPrompt(touch, candidates, config) {
  const managerName = txt(config.manager_name) || "the property manager";
  const companyName = txt(config.company_name) || "the property team";

  const rows = (candidates || []).map((lease) => ({
    lease_id: txt(lease.lease_id),
    tenant_first_name: txt(lease.tenant_first_name),
