    "Style: plain American English, 50 to 90 words, three or four short sentences, no exclamation marks, no bullets, no emoji, no 'I hope this finds you well'.",
    "Return only JSON matching the requested schema.",
  ].join("\n");
}

function buildDraftBatchPrompt(candidates, config) {
  const rows = candidates.map((lease) => ({
    lease_id: lease.lease_id,
    tenant_first_name: lease.tenant_first_name,
    unit: lease.unit,
    tenure_months: lease.tenure_months,
    manager_name: config.manager_name || "Maya Chen",
    company_name: config.company_name || "Harborview Property Management",
  }));

  return [
    `Write exactly ${rows.length} check-in drafts: one draft for each input row, no more and no fewer.`,
    "Return the drafts in the same order as the input rows. Do not create multiple variants for any row.",
    "Every input lease_id must appear exactly once in the drafts array. Do not duplicate a lease_id and do not omit any lease_id.",
    "Each draft must include the exact lease_id from the input row, a subject, and a body.",
    "Vary the structure and phrasing between drafts. Do not use a mail-merge template.",
    "Do not include email addresses in any output.",
    "",
    JSON.stringify({ rows }, null, 2),
  ].join("\n");
}

function buildRetryPrompt(failures, config) {
  const rows = failures.map((failure) => ({
    lease_id: failure.lease.lease_id,
    tenant_first_name: failure.lease.tenant_first_name,
    unit: failure.lease.unit,
    tenure_months: failure.lease.tenure_months,
    manager_name: config.manager_name || "Maya Chen",
    company_name: config.company_name || "Harborview Property Management",
    previous_violations: failure.violations,
  }));

  if (!rows.length) {
    return "No drafts failed deterministic guardrails. Return {\"drafts\":[]}.";
  }

  return [
    "Rewrite only the rows below. The previous drafts failed deterministic guardrails.",
    "Avoid every named violation. Return a JSON object with a drafts array using the exact lease_id values.",
    "",
    JSON.stringify({ failed_rows: rows }, null, 2),
  ].join("\n");
}

function eligibleDraftRows(leases, cohort) {
  const seen = new Set();
  return toArray(leases)
    .filter((lease) => normalizeText(lease.lease_id))
    .filter((lease) => normalizeText(lease.cohort) === normalizeText(cohort || "90"))
    .filter((lease) => normalizeText(lease.status).toUpperCase() === "PENDING")
    .filter((lease) => normalizeBool(lease.email_valid))
    .filter((lease) => !normalizeBool(lease.opted_out))
    .sort((a, b) => Number(a.days_to_expiry || 9999) - Number(b.days_to_expiry || 9999))
    .filter((lease) => {
      const leaseId = normalizeText(lease.lease_id);
      if (seen.has(leaseId)) return false;
      seen.add(leaseId);
      return true;
    });
}

function makeDraftRow(lease, draft, refToken, status, guard) {
  const subject = status === "DRAFT"
    ? appendRefToken(draft.subject, refToken)
    : appendRefToken("Needs manager wording", refToken);
  const body = status === "DRAFT"
    ? normalizeText(draft.body)
    : `Guardrail failed: ${guard.violations.join("; ")}`;

  return {
    ...lease,
    status,
    draft_subject: subject,
    draft_body: body,
    ref_token: refToken,
    _guardrail: guard,
  };
}

function finalizeDraftsFromBatch(candidates, firstDrafts, retryDrafts, config) {
  const firstByLease = new Map(firstDrafts.map((draft) => [draft.lease_id, draft]));
  const retryByLease = new Map(retryDrafts.map((draft) => [draft.lease_id, draft]));
  const usedTokens = new Set();
  const finalRows = [];
  const failures = [];

  for (const lease of candidates) {
    const first = firstByLease.get(lease.lease_id);
    let draft = first ? repairDraftForLease(lease, first) : null;
    let guard = draft ? guardDraft(lease, draft.subject, draft.body) : {
      ok: false,
      violations: ["missing draft from model output"],
      word_count: 0,
      question_count: 0,
    };

    if (!guard.ok) {
      failures.push({ lease, violations: guard.violations });
      const retry = retryByLease.get(lease.lease_id);
      if (retry) {
        const repairedRetry = repairDraftForLease(lease, retry);
        const retryGuard = guardDraft(lease, repairedRetry.subject, repairedRetry.body);
        if (retryGuard.ok) {
          draft = repairedRetry;
          guard = retryGuard;
        } else {
          guard = retryGuard;
          draft = repairedRetry;
        }
      }
    }

    const token = refTokenForLease(lease, usedTokens);
    finalRows.push(makeDraftRow(
      lease,
      draft || { subject: "", body: "" },
      token,
      guard.ok ? "DRAFT" : "REVIEW_FAILED",
      guard,
    ));
  }

  return {
    rows: finalRows,
    failures,
    generated_count: finalRows.filter((row) => row.status === "DRAFT").length,
    review_failed_count: finalRows.filter((row) => row.status === "REVIEW_FAILED").length,
    model: config.model_draft || "gpt-5.6-luna",
  };
}

function prepareApprovalChanges(action, body, leases) {
  const normalizedAction = normalizeText(action).toLowerCase();
  const leaseId = normalizeText(body.lease_id);
  const changes = [];

  function rowById(id) {
    return toArray(leases).find((lease) => normalizeText(lease.lease_id) === id);
  }

  function applyEditedFields(lease) {
    const updated = { ...lease };
    if (Object.prototype.hasOwnProperty.call(body, "edited_subject")) {
      updated.draft_subject = appendRefToken(body.edited_subject, normalizeText(lease.ref_token));
    }
    if (Object.prototype.hasOwnProperty.call(body, "edited_body")) {
      updated.draft_body = normalizeText(body.edited_body);
    }
    return updated;
  }

  if (normalizedAction === "approve_all") {
    for (const lease of toArray(leases)) {
      if (normalizeText(lease.status).toUpperCase() !== "DRAFT") continue;
      const guard = guardDraft(lease, lease.draft_subject, lease.draft_body);
      if (guard.ok) changes.push({ ...lease, status: "APPROVED", _approval_action: "approve_all" });
    }
    return changes;
  }

  if (!leaseId) throw new Error("lease_id is required for approve, edit, and skip actions.");
  const lease = rowById(leaseId);
  if (!lease) throw new Error(`No lease row found for lease_id ${leaseId}.`);

  if (normalizedAction === "skip") {
    changes.push({ ...lease, status: "SKIPPED", _approval_action: "skip" });
    return changes;
  }

  if (!["edit", "approve"].includes(normalizedAction)) {
    throw new Error(`Unsupported approval action: ${normalizedAction}`);
  }

  const updated = applyEditedFields(lease);
  const guard = guardDraft(updated, updated.draft_subject, updated.draft_body);
  if (!guard.ok) {
    throw new Error(`Edited draft failed guardrail: ${guard.violations.join("; ")}`);
  }

  updated.status = normalizedAction === "approve" ? "APPROVED" : normalizeText(lease.status).toUpperCase() || "DRAFT";
  updated._approval_action = normalizedAction;
  changes.push(updated);
  return changes;
}

function buildFooter(config) {
  const company = config.company_name || "Harborview Property Management";
  const manager = config.manager_name || "Maya Chen";
  return [
    "",
    "--",
    manager,
    company,
    "Demo check-in only. This is not a renewal offer, notice, or lease document.",
  ].join("\n");
}

function prepareSendCandidates(body, leases, config) {
  const requested = Array.isArray(body.lease_ids)
    ? new Set(body.lease_ids.map((id) => normalizeText(id)).filter(Boolean))
    : null;
  const demoEmail = normalizeText(config.demo_recipient_email).toLowerCase();
  const footer = buildFooter(config);
  const delay = Math.max(0, Number(config.send_delay_seconds || 0) || 0);

  return toArray(leases)
    .filter((lease) => normalizeText(lease.lease_id))
    .filter((lease) => !requested || requested.has(normalizeText(lease.lease_id)))
    .filter((lease) => normalizeText(lease.status).toUpperCase() === "APPROVED")
    .filter((lease) => normalizeBool(lease.email_valid))
    .filter((lease) => !normalizeBool(lease.opted_out))
    .filter((lease) => guardDraft(lease, lease.draft_subject, lease.draft_body).ok)
    .sort((a, b) => {
      const aPriority = demoEmail && normalizeText(a.email).toLowerCase() === demoEmail ? 0 : 1;
      const bPriority = demoEmail && normalizeText(b.email).toLowerCase() === demoEmail ? 0 : 1;
      if (aPriority !== bPriority) return aPriority - bPriority;
      return normalizeText(a.tenant_name).localeCompare(normalizeText(b.tenant_name));
    })
    .map((lease, index) => ({
      ...lease,
      status: "SENDING",
      _send_body: `${normalizeText(lease.draft_body)}${footer}`,
      _sender_name: config.manager_name || "Maya Chen",
      _send_delay_seconds: index === 0 ? 0 : delay,
      _is_demo_priority: demoEmail && normalizeText(lease.email).toLowerCase() === demoEmail,
    }));
}

function sentEventForLease(lease, sentAt) {
  return {
    event_id: `sent-${sentAt.replace(/[^0-9A-Za-z]/g, "")}-${normalizeText(lease.lease_id)}`,
    lease_id: lease.lease_id,
    event_type: "SENT",
    reply_text: "",
    intent: "",
    grievance_category: "",
    grievance_summary: "",
    urgency: "",
    compliance_flag: "",
    confidence: "",
    requires_human: false,
    created_at: sentAt,
  };
}

const decided = $('Decide Action').first().json;
const lease = decided.lease;
const config = decided.config || {};
const action = decided.action;
const nowIso = new Date().toISOString();

const out = {
  action,
  record_id: decided.record_id,
  chat_id: decided.chat_id,
  callback_query_id: decided.callback_query_id,
  outcome: decided.outcome,
  needs_gmail: false,
  lease,
  config,
  airtable_fields: null,
  log_row: null,
  config_write: null,
  next_record_id: decided.next_record_id || '',
  pending_config_record_id: decided.pending_config_record_id || '',
  text: decided.text || '',
  card_type: 'plain',
};

if (decided.outcome !== 'ok' || !lease) {
  return [{ json: out }];
}

// Pull the model's reply draft when this action produced one.
let modelDraft = null;
if (decided.needs_openai) {
  try {
    const raw = $('OpenAI Draft Reply').first().json;
    const parsed = extractJsonCandidate(raw);
    if (parsed && (parsed.body || parsed.subject)) {
      modelDraft = { subject: String(parsed.subject || ''), body: String(parsed.body || '') };
    }
  } catch (error) {
    modelDraft = null;
  }
}

const footer = buildFooter(config);
const refSubject = String(lease.draft_subject || '').trim();

function replySubject() {
  return refSubject ? (/^re:/i.test(refSubject) ? refSubject : 'Re: ' + refSubject) : 'Re: your message';
}

if (action === ACTIONS.APPROVE_SEND) {
  // Guardrails re-run here, not just at drafting time, because a manager may have
  // edited draft_body in Airtable since. Whatever is about to be sent is what gets
  // checked.
  const guard = guardDraft(lease, lease.draft_subject, lease.draft_body);
  if (!guard.ok) {
    out.outcome = 'guard_failed';
    out.text = 'This message was not sent. The edited wording failed the safety checks: '
      + guard.violations.join('; ') + '. Fix it in Airtable and approve again.';
    return [{ json: out }];
  }
  out.needs_gmail = true;
  out.to_email = lease.email;
  out.subject = lease.draft_subject;
  out.body = String(lease.draft_body || '') + footer;
  out.airtable_fields = { status: 'SENT', sent_at: nowIso };
  out.log_row = {
    event_type: 'SENT',
    channel: 'EMAIL',
    direction: 'OUTBOUND',
    message_text: lease.draft_subject,
    approved_by: config.manager_name || 'manager',
  };
  out.text = 'Sent to ' + lease.tenant_name + ' at ' + lease.unit + '.';
} else if (action === ACTIONS.SKIP_DRAFT) {
  out.airtable_fields = { status: 'PENDING', touch_stage: 'NONE', draft_subject: '', draft_body: '' };
  out.log_row = { event_type: 'SKIPPED', channel: 'SYSTEM', direction: 'INTERNAL', message_text: 'Draft skipped by manager' };
  out.text = 'Skipped ' + lease.tenant_name + '. Nothing was sent.';
} else if (action === ACTIONS.EDIT_DRAFT) {
  // Arm an edit. The field chosen depends on what the card was showing.
  const field = String(lease.assist_draft || '').trim() ? 'assist_draft' : 'draft_body';
  out.config_write = { key: 'pending_edit', value: lease.record_id + '|' + field };
  out.text = 'Send me the new wording for ' + lease.tenant_name
    + ' as a plain message. It replaces the current text and still has to pass the safety checks.';
} else if (action === 'edt_apply') {
  const field = decided.edit_field === 'assist_draft' ? 'assist_draft' : 'draft_body';
  const newText = String(decided.edit_text || '').trim();

  // The manager's own wording is checked exactly like the model's.
  const guard = field === 'assist_draft'
    ? guardReply(lease, replySubject(), newText)
    : guardDraft(lease, lease.draft_subject, newText);

  if (!guard.ok) {
    out.outcome = 'guard_failed';
    out.text = 'That wording was not saved. It failed the safety checks: '
      + guard.violations.join('; ') + '. Send a revised version.';
  } else {
    const fields = {};
    fields[field] = newText;
    out.airtable_fields = fields;
    out.config_write = { key: 'pending_edit', value: '' };
    out.log_row = {
      event_type: 'DRAFTED',
      channel: 'SYSTEM',
      direction: 'INTERNAL',
      message_text: 'Manager edited the ' + field.replace('_', ' '),
      approved_by: config.manager_name || 'manager',
    };

    const updated = Object.assign({}, lease, fields);
    if (field === 'assist_draft') {
      const card = assistApprovalCard(updated);
      out.text = card.text;
      out.card_type = 'assist';
    } else {
      const card = draftApprovalCard(updated, {});
      out.text = card.text;
      out.card_type = 'draft';
    }
  }
} else if (action === ACTIONS.NEXT_DRAFT) {
  const stillPending = String(lease.status || '').toUpperCase() === 'AWAITING_APPROVAL';
  if (!stillPending) {
    out.text = lease.tenant_name + ' is no longer awaiting approval (status '
      + String(lease.status || '').toUpperCase() + ').';
  } else {
    const card = draftApprovalCard(lease, {
      position: decided.queue_position,
      total: decided.queue_total,
    });
    out.text = card.text;
    out.card_type = 'draft';
    out.next_record_id = decided.next_record_id || '';
  }
} else if (action === ACTIONS.DRAFT_ASSIST) {
  if (!modelDraft) {
    out.outcome = 'openai_failed';
    out.text = 'The reply could not be drafted. Nothing was sent. Write this one yourself.';
  } else {
    const guard = guardReply(lease, modelDraft.subject, modelDraft.body);
    if (!guard.ok) {
      out.outcome = 'guard_failed';
      out.text = 'The drafted reply failed the safety checks (' + guard.violations.join('; ') + '). Nothing was sent.';
    } else {
      // Stored without the footer: the footer mentions renewal and lease wording
      // that the reply guardrail would reject on the re-check at send time.
      const draftText = modelDraft.body;
      out.airtable_fields = { assist_draft: draftText };
      const card = assistApprovalCard(Object.assign({}, lease, { assist_draft: draftText }));
      out.text = card.text;
      out.card_type = 'assist';
    }
  }
} else if (action === ACTIONS.SEND_ASSIST) {
  const guard = guardReply(lease, replySubject(), lease.assist_draft);
  if (!guard.ok) {
    out.outcome = 'guard_failed';
    out.text = 'This reply was not sent. The wording failed the safety checks: '
      + guard.violations.join('; ') + '. Fix it in Airtable and send again.';
    return [{ json: out }];
  }
  out.needs_gmail = true;
  out.to_email = lease.email;
  out.subject = replySubject();
  out.body = String(lease.assist_draft || '') + footer;
  out.airtable_fields = { assist_draft: '' };
  out.log_row = {
    event_type: 'ASSIST_SENT',
    channel: 'EMAIL',
    direction: 'OUTBOUND',
    message_text: String(lease.assist_draft || '').slice(0, 900),
    approved_by: config.manager_name || 'manager',
  };
  out.text = 'Reply sent to ' + lease.tenant_name + '.';
} else if (action === ACTIONS.DISCARD_ASSIST) {
  out.airtable_fields = { assist_draft: '' };
  out.log_row = { event_type: 'SKIPPED', channel: 'SYSTEM', direction: 'INTERNAL', message_text: 'Drafted reply discarded' };
  out.text = 'Discarded. Nothing was sent to the resident.';
} else if (action === ACTIONS.MARK_RESOLVED) {
  const openedAt = lease.issue_opened_at || lease.sent_at || nowIso;
  const elapsedMs = Math.max(0, new Date(nowIso) - new Date(openedAt));
  const elapsedDays = Math.round((elapsedMs / 86400000) * 10) / 10;
  const turnoverCost = Number(config.avg_turnover_cost || 3900);

  const fields = {
    issue_status: 'RESOLVED',
    issue_resolved_at: nowIso,
    days_to_resolve: elapsedDays,
    status: 'RESOLVED',
    turnover_exposure: 0,
  };

  if (modelDraft) {
    const guard = guardReply(lease, modelDraft.subject, modelDraft.body);
    fields.assist_draft = guard.ok ? modelDraft.body : '';
  }

  out.airtable_fields = fields;
  out.log_row = {
    event_type: 'RESOLVED',
    channel: 'SYSTEM',
    direction: 'INTERNAL',
    message_text: 'Issue marked resolved after ' + elapsedDays + ' days',
    approved_by: config.manager_name || 'manager',
  };

  const card = resolutionCard(
    Object.assign({}, lease, { days_to_resolve: elapsedDays, assist_draft: fields.assist_draft || '' }),
    { exposure_recovered: turnoverCost }
  );

  out.text = card.text;
  out.card_type = fields.assist_draft ? 'resolution' : 'plain';
} else if (action === ACTIONS.SEND_CONFIRMATION) {
  const guard = guardReply(lease, replySubject(), lease.assist_draft);
  if (!guard.ok) {
    out.outcome = 'guard_failed';
    out.text = 'The confirmation was not sent. The wording failed the safety checks: '
      + guard.violations.join('; ') + '. Fix it in Airtable and send again.';
    return [{ json: out }];
  }
  out.needs_gmail = true;
  out.to_email = lease.email;
  out.subject = replySubject();
  out.body = String(lease.assist_draft || '') + footer;
  out.airtable_fields = { confirmation_sent_at: nowIso, assist_draft: '' };
  out.log_row = {
    event_type: 'CONFIRMATION_SENT',
    channel: 'EMAIL',
    direction: 'OUTBOUND',
    message_text: String(lease.assist_draft || '').slice(0, 900),
    approved_by: config.manager_name || 'manager',
  };
  out.text = 'Confirmation sent to ' + lease.tenant_name + '.';
} else {
  out.outcome = 'unknown_action';
  out.text = 'That button is not recognised.';
}

return [{ json: out }];

function flattenAirtable(items) {
  const out = [];
  for (const item of items || []) {
    const records = item && item.json && Array.isArray(item.json.records) ? item.json.records : [];
    for (const record of records) {
      out.push(Object.assign({ record_id: record.id }, record.fields || {}));
    }
  }
  return out;
}

function configMap(rows) {
  const map = {};
  for (const row of rows || []) {
    if (row.key) map[row.key] = row.value;
  }
  return map;
}


const applied = $('Apply Action').first().json;
const nowIso = new Date().toISOString();

let gmailId = '';
let gmailFailed = false;
if (applied.needs_gmail) {
  try {
    const sent = $('Gmail Send Resident Message').first().json;
    gmailId = String(sent.id || sent.messageId || '');
    if (sent.error) gmailFailed = true;
  } catch (error) {
    gmailFailed = true;
  }
}

const writes = [];

// A failed Gmail send must be visible, never silent.
let fields = applied.airtable_fields;
let text = applied.text;

if (gmailFailed) {
  fields = { status: 'SEND_FAILED' };
  text = 'The send failed for ' + (applied.lease ? applied.lease.tenant_name : 'this resident') + '. Nothing reached the resident. Check the Gmail node.';
}

if (fields && applied.record_id) {
  writes.push({
    method: 'PATCH',
    table: 'Leases',
    body: { records: [{ id: applied.record_id, fields }], typecast: true },
  });
}

// Pending-edit state lives in the Config table so it survives restarts.
if (applied.config_write && !gmailFailed) {
  if (applied.pending_config_record_id) {
    writes.push({
      method: 'PATCH',
      table: 'Config',
      body: {
        records: [{
          id: applied.pending_config_record_id,
          fields: { value: applied.config_write.value, updated_at: nowIso },
        }],
        typecast: true,
      },
    });
  } else if (applied.config_write.value) {
    writes.push({
      method: 'POST',
      table: 'Config',
      body: {
        records: [{
          fields: {
            key: applied.config_write.key,
            value: applied.config_write.value,
            value_type: 'string',
            description: 'Draft currently awaiting edited wording from Telegram.',
            updated_at: nowIso,
          },
        }],
        typecast: true,
      },
    });
  }
}

if (applied.log_row && !gmailFailed) {
  const lease = applied.lease || {};
  writes.push({
    method: 'POST',
    table: 'Outreach Log',
    body: {
      records: [{
        fields: Object.assign(
          {
            event_id: applied.action + '-' + (lease.lease_id || applied.record_id) + '-' + Date.now(),
            lease_id: lease.lease_id || '',
            tenant_name: lease.tenant_name || '',
            gmail_message_id: gmailId,
            created_at: nowIso,
          },
          applied.log_row
        ),
      }],
      typecast: true,
    },
  });
}

return [{
  json: {
    writes,
    has_writes: writes.length > 0,
    chat_id: applied.chat_id,
    text,
    card_type: gmailFailed ? 'plain' : (applied.card_type || 'plain'),
    record_id: applied.record_id,
    next_record_id: applied.next_record_id || applied.record_id,
    callback_query_id: applied.callback_query_id,
    action: applied.action,
    outcome: gmailFailed ? 'send_failed' : applied.outcome,
  },
}];

const payload = $('Finalize Action').first().json;
if (!payload.has_writes) return [];
return (payload.writes || []).map((write) => ({ json: write }));

const payload = $('Finalize Action').first().json;
return [{
  json: {
    chat_id: payload.chat_id,
    text: payload.text,
    card_type: payload.card_type || 'plain',
    record_id: payload.record_id || '',
    next_record_id: payload.next_record_id || payload.record_id || '',
    callback_query_id: payload.callback_query_id,
    action: payload.action,
    outcome: payload.outcome,
  },
}];
